INSERT INTO "g2p_crop" ("id", "name", "description", "category_id", "known_for", "num_field_inspection_needed", "isolation_distance", "preferred_ecological_zone_id", "scientific_name", "centre", "varieties_count", "image_url", "display_name_amh", "taxonomy_type_code", "taxonomy_source_id", "taxonomy_category_code", "taxonomy_description", "record_source", "varieties_count_source", "taxonomy_match_method", "taxonomy_match_status", "category_source") VALUES
  (1, 'Maize ( Zea mays L.)', 'It was introduced to Ethiopia in 16th or 17th century.  It is grown in most parts of the
world over a wide range of environmental conditions, ranging between
500 latitudes north and south of equator. It also grows from sea level to
over 3000 meters above sea level.
In Ethiopia, maize grows from moisture stress areas to high rainfall
areas and from lowlands to the highlands. It is largely produced in
Western, Central, Southern and Eastern parts of the country', 1, 'Hybrid and Composite type which are used as staple food and others', 2, 300, 2, 'Zea mays L.', 'BKARC', 99, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Maize.jpg', 'በቆሎ', 'maize', 'croptype-592280314975', 'cereal', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (2, 'Bread wheat (Triticum aestivum L.)', 'Bread Wheat is one of the major cereal crops in the Ethiopian highlands, which range
between 6 and 16°N, 35 and 42°E, and from 1500 to 2800 m. 
Altitude plays an important role in the distribution of wheat production
through its influence on rainfall, temperature, and diseases. In Arsi,
Bale and Shewa regions, the soil, moisture and disease conditions
within the range of 1900-2300m altitude zone are favorable for the
production of early and intermediate maturing varieties of bread wheat.', 1, 'Specially for bread preparation ,  It is the major cereal crop', 5, 3, 2, 'Triticum aestivum', 'KARC', 129, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Bread wheat.jpg', 'የዳቦ ስንዴ', 'bread-wheat', 'croptype-333506573211', 'cereal', 'Ethiopia is the largest wheat producer in Sub-Saharan Africa. Wheat is one of the major cereal crops in the Ethiopian highlands, which range between 6 and 16oN, 35 and 42oE, and from 1500 to 2800 m. At present, wheat is produced solely under rain fed conditions. At national level, during 2014/15 cropping season 1, 663, 837.58 ha of land is covered by bread and durum wheat and 42 315,887.16 quintals were harvested from these land.

Altitude plays an important role in the distribution of wheat production through its influence on rainfall, temperature, and diseases. In Arsi, Bale and Shewa regions, the soil, moisture and disease conditions within the range of 1900-2300 m altitude zones are favorable for the production of early and intermediate maturing varieties of bread wheat. This is estimated to comprise 25% of the total wheat production area, while the remaining 75% falls in the 2300-2700 m altitude zone. There, early, intermediate and late varieties are grown. Soil types used for wheat production vary from well-drained fertile soils to waterlogged heavy vertisols.

So far, different varieties of bread wheat varieties have been released and/ or registered to satisfy the growing production demand of the farmers in the country', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (3, 'Durum Wheat', 'Triticum turgidum var.durum . 
Durum or macaroni wheat is indigenous to Ethiopia and it has been
under cultivation since ancient times. Ethiopia is considered to be the
center of genetic diversity of this crop. It is a tetraploid wheat species
and traditionally grown on heavy black clay soils (Vertisols) of the
central and northern highlands of Ethiopia between 1800-2800 meters
above sea level.', 1, 'To make spaghetti, macaroni and other  pastas.', 5, 3, 2, 'Triticum turgidum var. durum', 'DZARC', 41, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Durum wheat.jpg', 'የመኮሮኒ ስንዴ', 'durum-wheat', 'croptype-303724598967', 'cereal', 'Durum or macaroni wheat is indigenous to Ethiopia and it has been under cultivation since ancient times. Ethiopia is considered to be the center of genetic diversity of this crop. It is a tetraploid wheat species and traditionally grown on heavy black clay soil (Vertisols) of the central and northern highlands of Ethiopia between 1800-2800 meters above sea level. Accurate statistics on area and production of durum wheat in the county are difficult to obtain since they are lumped together with bread wheat.

In Ethiopia, durum wheat is consumed as leavened bread, common bread, macaroni, spaghetti, biscuits, pastries, and in various indigenous food preparations. The straw is mainly used for cattle feed and for fuel at times of scarcity. It has very narrow d=adaptation and lower yield potential as compared to bread wheat.

Although recommendations may vary from one region to another, the planting of newly improved durum wheat varieties are 2-3 weeks earlier than the normally used land races. In general, the improved varieties of durum wheat are highly beneficial in most of their qualities to agro industries.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (4, 'Food Barley', 'Hordeum vulgare', 1, 'The crop is now grown worldwide with  greater concentration in temperate areas and high altitudes of the  tropics and subtropics', 0, 0, NULL, 'Hordeum vulgare', 'SiARC', 37, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Barley.jpg', 'ገብስ', 'barley', 'croptype-315796933991', 'cereal', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'REVIEWED_TYPE_ALIAS', 'MATCHED', 'SQL_CROP_CATALOG'),
  (5, 'Malt Barley', 'Hordeum distichon', 1, 'The major (90%) raw material for beer  production. Characterized as two-rowed and six rowed barley in  which only the middle spiklet of each three produces seed, the other  two being sterile or male', 0, 0, NULL, 'Hordeum vulgare', 'SiARC', 27, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Barley.jpg', 'ገብስ', 'barley', 'croptype-315796933991', 'cereal', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'REVIEWED_TYPE_ALIAS', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (6, 'Tef ( Eragrostis tef)', 'Tef is a gluten-free an important cereal crop in Ethiopia. It is the most adapted crop in the diverse
agro-ecologies of the country.', 1, 'Tef is a gluten-free an important cereal crop in Ethiopia.', 2, 5, NULL, 'Eragrostis tef', 'DZARC', 61, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Tef.jpg', 'ጤፍ', 'tef', 'croptype-920196427806', 'cereal', 'Tef is a gluten-free an important cereal crop in Ethiopia. In 2020/21 cropping season, cereal crops were grown on 10,538,341.91 hectares of land. Of these, 2,928,206.26 hectares were allocated for Tef and the total production in the Meher season was about 55,099,615.14 quintals.

Outside Ethiopia there is a growing interest in using tef. For example, small scale commercial production of tef has begun in a few areas of the wheat belts of USA, Canada and Australia. Tef has been introduced to South Africa and cultivated as a forage crop, and in recent years cultivated as a cereal crop in Northern Kenya and The Netherlands.

Tef is endemic to Ethiopia and its major diversity is found only in that county. As with several other crops, the exact date and location for the domestication of Tef is unknown. However, there is not doubt that it is a very ancient crop in Ethiopia, where domestication took place before the birth of Christ.

In Ethiopia, tef is traditionally grown as a cereal crop. The grain is ground to flour, which is mainly used for making popular pancake-like local bread called enjera and sometimes for making porridge. The grain is also used to make local alcoholic drinks, called tela and katikala. Tef starw, besides being the most appreciated feed for cattle, is also used to reinforce mud and plaster the walls of tukuls and local grain storage facilities called goteras. Tef grain, owing to its high mineral content, has started to be used in mixtures with soybean, chickpea and other grains in the baby food industry. It is the most adapted crop in the diverse agro-ecologies of the country.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (7, 'Sorghum (Sorghum bicolor)', 'Sorghum is one of the major crops produced in Ethiopia, and it is the
fourth important crop in terms of area coverage and volume of
production. It is adapted to a wide range of environment, and hence
can be produced in the high lands, medium altitude and low land areas.
It is widely produced more than any other crops, in the areas where
there is moisture stress.', 1, 'cultivated for its edible grain, Sweet sorghums are sorghum cultivars that are primarily grown for  foliage; they are shorter than those grown for grain.', 4, 200, NULL, 'Sorghum bicolar', 'MARC', 59, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/sorghum.jpg', 'ማሽላ', 'sorghum', 'croptype-520366975124', 'cereal', 'Sorthum is one of the major crops produced in Ethiopia, and it is the fourth important crop in terms of area coverage and volume of prouction. It is adapted to a wide range of environment, and henve can be producted in the high lands, medium altitude and low land areas. It is widely produced more than any other crops, in thee areas where there is moisture stress. In 2020/21 cropping season, sorhum is produced on about 1,6679,277.06 ha of land from which 45,173,502.18 quintals of yield are obtained', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (8, 'Millet', '', NULL, 'Soil acidity tolerant', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'UNRESOLVED', 'UNRESOLVED', 'UNRESOLVED'),
  (9, 'Rice', 'Oryza sativa L. or Oryza glaberrima', 1, 'Paddy Agriculture', 0, 0, NULL, 'Oryza sativa L. or Oryza glaberrima', 'FNRTC', 26, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Rice.jpg', 'ሩዝ', 'rice', 'croptype-383064785940', 'cereal', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (10, 'Finger Millet', 'Eleusine coracana', 1, 'Liquor', 2, 3, NULL, 'Eleusine coracana', 'MARC', 20, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/finger_millet.webp', 'ዳጉሳ', 'finger-millet', 'croptype-678775192009', 'cereal', 'Finger millet, Amharic Dagusa also known as African millet, is an annual plant widely grown as a cereal in the arid areas of Africa and Asia. Finger millet is originally native to the Ethiopian Highlands and was introduced into India approximately 4000 years ago. It is very adaptable to higher elevations and is grown in the Himalaya up to 2,300 meters in elevation.

In Ethiopia, finger millet is produced in North Gonder, East Gojam, some parts of Tigray and West Wollega. The seed should be planted into a well-prepared seedbed, not deeper than 2-3 cm. Finger millet requires a well-distributed rainfall during growth, due to its expensive but shallow root system. Whilst moisture requirement is rather high, the crop should be grown on well drained soils with average annual rainfall above 800-900 mm.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (12, 'Triticale', 'X-Triticosecale', 1, 'Tolerant of soil acidity', 0, 0, NULL, 'X-Triticosecale', 'AdARC', 10, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/triticale.webp', NULL, 'triticale', 'croptype-554879135329', 'cereal', 'Triticale (X. Triticosecale) is a man-made crop developed by crossing wheat (Triticum turgidum or Triticum aestivum) with Rye (Secale cereale). In Ethiopia, triticale is a recent introduction. Triticale can be cultivated in a wide range of agro-ecologies, ranging from sea level to over 3000 m.a.s.l. Drought and frost tolerance are the primary advantages that triticale has over other cereal crops. It also exhibits better performance under acidic and degraded soils compared with many other cereals. Triticale has high biomass production and re-growth capacity for grazing. The yield advantage over wheat and barley is also significant.

Triticale is adapted to a wide range of soil conditions ranging from sandy to clay soil types. It requires an average of 500-600 mm rainfall, well distributed during the growing season. However, it can also perform well with as little as 350 mm of seasonal rainfall.

Most cultural practices for growing wheat can be applied directedly to triticale. Consequently, the fertilization, seedbed preparation, seeding depth and seeding methods used for wheat are acceptable for triticale. Triticale can be used for making enjera, pasta, pastry, bread, tella and beer. Triticale bread and enjera products have been well accepted by farmers in South Gondar.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (13, 'Emmer wheat (Aja)', 'Triticum dicoccum', 1, 'Maternal care', 2, 3, NULL, 'Triticum dicoccum', 'SinARC', 3, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Emmer wheat.jpg', 'አጃ', 'emmer-wheat', 'croptype-492103822592', 'cereal', 'Emmer wheat (Triticum dicoccum) is not strictly African; it is originated in the Near East. Indeed, it is one of the first cereals ever domesticated and was part of the early agriculture of the Fertile Crescent.

Farmers have it in fields perhaps as far back as 10,000 years ago. For several thousand years it remained a major cereal throughout the Middle East and North Africa. Then people switched to durum wheat, the type now used worldwide to make spaghetti, macaroni and other pastas. Farmers preferred it because its grain was free threshing (the seed fell out of its husk quite easily), and during the past 2,000 years or so the older form, emmer wheat, became an abandoned wheat. At national level, during 2020/21 cropping season 15,502.18 ha of land is covered by Emmer (aja) wheat and about 305,403.43 quintals are produced in this cropping season.
Emmer, locally known as Aja, is used in various ways. Some is ground into flour and baked into special bread (kita). Some is crushed and cooked with milk or water to make porridge (Genfo). And some is mixed with boiling water and butter to produce gruel. With emmer''s high protein content and smooth and easily digestible starch, infants and nursing mothers especially favor the gruel.

Source: Crop Variety Register, IssueNo. 24. 2021. MoA', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (14, 'Buck wheat', 'Buck wheat (Fagopyrum esculentum Monench) is a recent introduction
where its cultivation and use is new to Ethiopia. It is relatively low
yielder compared to other grain crops, however, its unique characters
such as its ability to perform better relatively on poor soils and its quick
maturity, suiting areas with very short rains and as a catch crop where
other crops failed or planting is delayed, makes it important.', 10, 'Is a recent introduction  where its cultivation and use is new to Ethiopia', 3, 3, 1, 'Fagopyrum esculentum Moench', 'DZARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Buck wheat.jpg', NULL, 'buck-wheat', 'croptype-432965158580', 'cereal', 'Buck wheat (Fagopyrum esculentum Moench) is a recent introduction where its cultivation and use is new to Ethiopia. It is relatively low yielder compared to other grain crops, however, its unique characters such as its ability to perform better relatively on poor soils and its quick maturity, suiting areas with very short rains and as a catch crop where other crops failed or planting is delayed, makes it important.

Though the grain is used in ways similar to cereals, buckwheat is a non-cereal, broadleaved herbaceous plant that flowers prolifically over a period of several weeks belonging to plygonaceae family.

The grain is a source of human food where the flour and /or groats could be used for making different recipes either solely or mixed with other cereal grains; it is also a good feed source to poultry and livestock. The extended nectar supply, for a month or more, for bees makes buckwheat popular among beekeepers. Besides, it is also an important smother and green manure crop.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (15, 'Pearl millet', 'Pennisetum glaucum (L.)R. Br.', 1, 'production systems characterized by  drought, low soil fertility, and high temperature', 0, 0, NULL, 'Pennisetum glaucum L.R.Br', 'MARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/pearl_millet.webp', NULL, 'pearl-millet', 'croptype-809346300724', 'cereal', 'Pearl millet is the most widely grown type of millet. Grown in Africa and the Indian subcontinent since prehistoric times, it is generally accepted that pearl millet originated in Africa and was subsequently introduced into India. Its origin has been traced to tropical Africa. The center center of diversity for the crop is in the Sahel zone of West Africa. Cultivation subsequently spread to east and southern Africa, and southern Asia.

Pearl millet is a new crop for Ethiopian farmers both in terms of cultivation and utilization, indicating the urgent needed for further study. Millet being a highly cross-pollinated crop, maintenance of seed-purity is a challenge that needs higher attention. The seeds of millet ripen first in the upper part of the head and then successively downward.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (16, 'Foxtail millet', 'Setaria italic', 1, 'It performs well in  soils with high salinity or low pH. Because of its tolerance to difficult  growing conditions, it can be grown in areas where other cereal crops,  such as maize or wheat, would not survive.', 0, 0, NULL, 'Setaria italic', 'MARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Foxtail millet.jpg', NULL, 'foxtail-millet', 'croptype-815519582877', 'cereal', 'It is the second most widely planted species of millet, and the most important in East Asia. It has the longest history of cultivation among the millets, having been grown in China since sometime in the sixth millennium BC. Other names for foxtail millet include Italian millet, German millet, Chinese millet, and Hungarian millet.

It is an annual grass with slim, vertical, leafy stems which can reach a height of 120-200 cm. The seed head is a dense, hairy panicle 5-30 cm long. The small seeds, around 2 mm in diameter, are encased in a thin, papery hull which is easily removed in threshing. Seed color varies greatly between varieties. It is a warm season crop, typically planted in late spring. Its early maturity and efficient use of available water make it suitable for rising in dry areas.

Nutrient composition is similar to common millet, approximately 11% of protein, 4% oil, and 6.7% of crude fiber. Foxtail millet grain has higher content of essential amino acids, vitamins (thiamine, riboflavin, niacin).', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (17, 'Quinoa', 'Chenopodium quinoa Willd', 1, 'Gibito', 0, 0, NULL, 'Chenopodium quinoa Willd', 'MARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Quinoa.jpg', 'ኪዩና', 'quinoa', 'croptype-903755949559', 'cereal', 'Will be updated', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (18, 'Food oat', 'Avena sativa', NULL, 'Food', 0, 0, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'UNRESOLVED', 'UNRESOLVED', 'UNRESOLVED'),
  (19, 'Faba bean', 'Vicia faba', 2, 'It is widely used for food and has high protein content. Due to its  nitrogen fixing capacity it is used in crop rotation.', 2, 0, NULL, 'Vicia faba', 'HARC', 33, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Faba bean.jpg', NULL, 'faba-bean', 'croptype-720981978697', 'food-legume', 'Ethiopia is probably one of the primary centers of diversification for faba bean. Although the small seeded type of the Ethiopian faba bean is not well studied, there are some reports of tremendous diversity in protein content, chocolate spot and leaf rust resistance.
Faba bean is produced in many regions of Ethiopia. The major producing regions are Tigray, Gondar, Gojjam, Wollega, Wollo, Gamo Gofa and Shoa.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (20, 'Field pea', 'Pisum sativum', 2, 'It is widely used for food because of its highest protein contents', 2, 3, NULL, 'Pisum sativum', 'HARC', 37, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Field pea.jpg', NULL, 'field-pea', 'croptype-346406364551', 'food-legume', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (21, 'Dekoko', 'Pisum sativum var. abyssinicum', 2, 'Dekoko is a pulse crop cultivated and developed in Ethiopia', 0, 0, NULL, 'Pisum sativum var. abyssinicum', 'AlaARC', 2, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/dekeko.jfif', 'ደቀቆ', 'dekoko', 'croptype-309960988062', 'food-legume', 'Dekoko is a pulse crop cultivated and developed in Ethiopia. The crop is known to grow in few pocket areas especially in South Tigray and North Wello regions. Dekoko grows from mid-altitude areas to highland areas. Although it is a cool season crop like field pea, the crop has an ability to grow in the low land areas such as Chercher where the elevation is 1720 masl. In higher areas, however, Dekoko needs late sowing (from mid July to early August) and a soil free of water logging condition. As Dekoko is a crop that matures within three months of planting, it is usually weeded once or twice before it produces tenrils and flowers but latter stages it is difficult to differentiate the root with weeds and usually uprooted with weed plants. The crop grows best on different types of soils with well-drained.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (22, 'Chickpea', 'Cicer arietinum', 2, 'Two types of chickpea produced globally, namely desi and  kabuli chickpeas. Kabuli chickpeas have a larger cream-colored seed  with a thin seed coat whereas the desi type has a smaller', 2, 3, NULL, 'Cicer arietinum', 'DZARC', 27, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/chickpea.jpg', 'ሽምብራ', 'chickpea', 'croptype-731005222916', 'food-legume', 'Chickpea is one of the major highland pulse crop widely grown in the highland and semi-highland regions of Ethiopia mainly on clay soil and fixes atmospheric nitrogen in soils and thus improves soil febrility and saves fertilizer costs in subsequent crops. In 2020/21 cropping season, 220,719.20 hectares of land was covered with chickpea and the production was estimated at about 4,573,193.70 quintals. Because of its multiple importance, the crop is widely produced by the Ethiopian farmers. Chickpea is widely used for food for its high protein content. Apart from this, because of its ability to fix nitrogen it is used in crop rotation with the nationally important cereal crops like wheat, tef and barley.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (23, 'Cowpea', 'Vigna ungulculata', 2, 'Can be  grown in relatively infertile sandy soils with a minimum annual rainfall  of 200mm. It is a fast growing, drought resistant crop.', 2, 3, NULL, 'Vigna ungulculata', 'MARC', 3, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Cowpea.jpg', NULL, 'cowpea', 'croptype-201421200829', 'food-legume', 'Cowpea has been cultivated for many centuries in the developing world and well adapted to the stressful growing condition of the tropics and has excellent nutritional qualities. It is a grain legume, which can be grown in relatively infertile sandy soils with a minimum annual rainfall of 200 mm. It is a fast growing, drought resistant crop, which also improves soil fertility by fixing atmospheric nitrogen. Cowpea grain typically contains 230-250 g/kg crude protein (CP) and 500-670 g/kg starch on a dry matter bases and cowpea forage, i.e. the crop residue after harvesting grain, 210 CP and 600 g digestible dry matter per Kg dry matter.
Cowpea is primarily used in the form of dry seed cooked as a pulse in a large variety of dishes. Green beans or cut green pods used as a vegetable are of secondary importance. In some areas of semi humid tropics the cowpea provides more than half the plant protein in human diets. Sometimes cowpea is also grown for forage and as a cover crop.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (24, 'Lentil', 'Lens culinaris.', 2, 'Largely produced in the highland & semi-highland regions of the  country mainly on clay soil.', 2, 0, NULL, 'Lens culinaris', 'DZARC', 13, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Lentil.jpg', 'ምስር', 'lentil', 'croptype-606234725254', 'food-legume', 'Lentil is one of the highland crops widely grown in Ethiopia. It is largely produced in the highland & semi-highland regions of the county mainly on clay soil. During 2020/21 cropping season, 84,511.63 hectares of land is covered with Lentil and about 1,130,178.82 quintals were produced. This crop is widely used for food because of its high protein content. Apart from this, due to its ability to fix nitrogen, it is used in crop rotation with the nationally important crops. Although the above mentioned realities indicate the national importance of lentil, the national yield is only about 8.35 quintals per hectare.

The lentil is a much-branched annual, up to 18 inches high, with slender, angular stems. Its leaves are pinnate, with 4-7 pairs of more or less oval leaflets, about 1/2 inches long. The small white flowers are papilionaceous with a large upper peta, two lateral petals, and two narrow petals between these.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (25, 'Common/Haricot/ bean', 'Phaseolus vulgare', 2, 'Haricot bean also known as common bean is an herbaceous annual  plant domesticated independently in ancient Mesoamerica and the  Andes, and now grown worldwide for its edible bean, popular both dry  and as a green bean', 2, 0, NULL, 'Phaseolus vulgare', 'MARC', 75, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Haricot bean.jpg', NULL, 'haricot-bean', 'croptype-391765061369', 'food-legume', 'Haricot bean is one of the lowland pulse crops produced in the hot humid regions of Ethiopia. It has been known as an export crop for long period of time contributing to the foreign exchange earnings of the country.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'REVIEWED_TYPE_ALIAS', 'MATCHED', 'SQL_CROP_CATALOG'),
  (26, 'Soybean', 'Glycine max', 3, 'Is classed as an oilseed and  pulse. Fat-free (defatted) soybean meal is a primary, low-cost, source  of protein for animal feeds and most prepackaged meals; soy vegetable  oil is another valuable product of processing the soybean crop', 2, 3, NULL, 'Glycine max', 'JARC', 30, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/soybean.jpg', 'አኩሪ አተር', 'soybean', 'croptype-551595836628', 'oil-seeds', 'Soybean is an internationally known important pulse crop. It is used for different purposes. In the 2020/21 cropping season, this crop covers about 83,797.17 hectares of land with an estimated production not less than 2,086,763.89 quintals. Since the oil content is high (16% and above) it is used for edible oil production. The by-product is cheap and an important source of protein for both human consumption & animal feed. It can also be used as Soya milk and Soya meat.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (27, 'Grass pea/ ''''Guaya''''', 'Lathyrus sativus L.', 2, 'It is the cheapest source of protein in the diets of most  people', 0, 0, NULL, 'Lathyrus sativus L.', 'DZARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Grass pea.jpg', NULL, 'grass-pea', 'croptype-114934769727', 'food-legume', 'Grass pea is among the important highland pulses of Ethiopia grown on more than 143,893.57 hectares with the production of about 2,899,174.75 quintals in 2020/21 cropping season. It is one of the important crops of economic significance in Ethiopia which is the fifth most important pulse crop after faba bean, field pea, chickpea and haricot bean. It is the cheapest source of protein in the diets of most people. Grass pea is a highly popular food and feed legume in the farming system duet to its tolerance of drought, flooding and diseases and also its importance in ameliorating soil fertility. It is commonly grown as a double crop after the cereals; tef or barley.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'REVIEWED_TYPE_ALIAS', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (28, 'Mung bean', 'Vigna radiata L', 2, 'Mung bean is an ancient and well-known crop in Asia. It is often  included in rice or wheat-based cropping systems in the tropics and  subtropics', 0, 0, NULL, 'Vigna radiata L.', 'MARC', 6, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Mung bean.jpg', 'ማሾ', 'mung-bean', 'croptype-446541774435', 'food-legume', 'Mung bean is in the legume family of plants and is closely related to adzuki and cowpea. It is a warm season annual, highly branched and having trifoliate leaves like the other legumes. Both upright and vine types of growth habit occur in mung bean, with plants varying from one to five feet in length. The pale yellow flowers are borne in clusters of 12-15 near the top of the plant. Mature pods are variable in color (yellowish-brown to black), about five inches long, and contain 10 to 15 seeds', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (29, 'Fenugreek', 'Trigonella foenum-graecum', 10, 'Fenugreek is a plant in the family of Fabaceae. It is used both as an  herb (the leaves) and as a spice (the seed).', 0, 0, NULL, 'Trigonella foenum-graecum', 'SinARC', 7, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/fenugreek.jfif', 'አብሽ', 'fenugreek', 'croptype-537295686678', 'spices-condiments-medicinal-aromatic', 'Fenugreek is a plant in the family of Fabaceae. It is used both as an herb (the leaves) and as a spice (the seed). It is cultivated worldwide to a semi-arid crops. It is frequently used in curry. The word for fenugreek is Amharic is abesh, and the seed is often used in Ethiopia as a natural herbal medicine in the treatment of diabetes. It is also sometimes used as an ingredient in the production of clarified butter, its flour is used as a flavoring of the traditional bread and maintains soft texture of "tef enjera".

Major fenugreek producing countries are India, Argentina, Egypt, France, Spain, Turkey, Morocco and China. Fenugreek seed is widely used as a galactagogue (milk producing agent) by nursing mothers to increase inadequate breast milk supply. Since the maple syrup-like flavor is strong and not always liked, the seeds are ground to a powder and administered in capsules. Studies have shown that fenugreek is a potent stimulator of breast milk production and its use was associated with increases in milk production of as much as 900%.
According to Central Statistics Agency 2020/21 report, the total area under production was 42,344.28 hectares and the production was estimated to be over 507,472.35 quintals.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (30, 'Noug', 'Guizotia abyssinica L.', 3, 'Noug is an oil-seed crop, indigenous to Ethiopia and holds significant  promise for improving rural livelihoods in Sub-Saharan Africa. The  species is used in intercropping systems, grows on poor but also  extremely wet soils, and contributes to soil conservation', 2, 600, NULL, 'Guizotia abyssinica L.', 'HARC', 3, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Noug.jpg', 'ኑግ', 'noug', 'croptype-251134569325', 'oil-seeds', 'Noug is an oil seed crop, indigenous to Ethiopia and holds significant promise for improving rural livelihoods in Sub Saharan Africa. The species is used in intercropping systems, grows on poor but also extremely wet soils, and contributes to soil conservation. It contributes up to 50% of the Ethiopian oil-seed crop. Noug diversity is numerous in Ethiopia and Eritrea and local farmers are able to distinguish many landraces. Apart from Africa (East and South African countries), noug is cultivated in parts of South Asia, where it was introduced thousand years ago, and the West Indies.

Noug belongs to the Compositae family and is closely related to sunflower. It differs from domesticated sunflower mainly due to its high level of branching, numerous flower heads and small seeds. The oil content of noug seed varies from 30 to 50%. The fatty acid composition is typical for seed oils of the Compositae family with linoleic acid being the dominant components.

It is one of the major oil crops of Ethiopia with the highest share of area coverage. The oil quality is very high and is comparable to the cooking oils used in the developed countries. In 2020/21 cropping season, 191,766.00 ha of land was covered with noug and about 2,147,979.02 quintals were estimated to be produced.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (31, 'Linseed', 'Linum usitatissimum L.', 3, 'It is the second most important oil crop after Noug.', 2, 200, NULL, 'Linum usitatissimum L.', 'HARC', 14, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Linseed.jpg', 'ተልባ', 'linseed', 'croptype-551131664280', 'oil-seeds', 'In Ethiopia the seed is commonly roasted, ground and mixed with spices and some water to be served along with local breads. It is also consumed in soups, soft drinks and with porridges or cooked potatoes. Its industrial use is higher tan all other oil crops. Its highest contribution in paint, soap, lubricant and pharmaceutical factories helped to gain international attention. In the 2020/21 cropping season, 78,921.37 ha of land was covered with linseed and the production was estimated to be 804,566.42.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (32, 'Rapeseed', 'Brassica spp.', 3, 'Ground seeds are used to grease a bread-baking clay pan,  cure certain ailments or stomach upsets and prepare beverages; the  leaves of young plants are good source of vegetable relish. The oil,  very often adulterated with the premium oil from noug is the  commercial product', 2, 200, NULL, 'Brassica napus', 'HARC', 9, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Rapeseed.jpg', NULL, 'rapeseed', 'croptype-851624380964', 'oil-seeds', 'Different research data show that the crop has about 40-46% oil content. Even though the crop is widely produced in the coutnry, its high "erucic" and "linoleic" acids content has limited its use either for food or feed. In 2020/21 cropping season, 7,917.47 ha of land are covered with Brassica spp. and the annual production was estimated at 125,757.89 quintals.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (33, 'Sesame', 'Sesamum indicum.', 3, 'Sesame is used for food. The dried seeds are eaten in soups and, mixed  with sugar, are a popular sweet in Africa and Asia. It is used as a salad  and cooking oil. The oil is also used in the manufacture of margarine  and compound cooking fats', 2, 50, NULL, 'Sesamum indicum', 'HuARC', 30, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Sesame.jpg', 'ሰሊጥ', 'sesame', 'croptype-174776413012', 'oil-seeds', 'It is an annual short-day warm season plant and mostly grown as a rain fed crop in the rainy season in the semi-arid regions of the tropics and subtropics. In Ethiopia, sesame seed grows mainly in the Northern and Northwestern region. The sowing is done during June to mid September and harvesting is from October onwards. The country is one of the major sesame exporting nations, currently ranked at the fourth position in world markets. Types of Sesame Seed in Ethiopia are Humera, Gondar and Wollega types where Humera Sesame seed is the main type exported by the country. Sesame is used for food. The dried seeds are eaten in soups and, mixed with sugar, are a popular sweet in Africa and Asia. It is used as a salad and cooking oil. The oil is also used in the manufacture of margarine and compound cooking fats.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (34, 'Groundnut', 'Arachis hypogaea', 3, 'It is a major  cash crop and widely grown in all the tropical and sub tropical regions  of the world for direct use as food, oil, and high protein meal.', 2, 0, NULL, 'Arachis hypogaea', 'WARC', 18, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Groundnut.jpg', 'ኦቾሎኒ', 'groundnut', 'croptype-684407673538', 'oil-seeds', 'Ground is a species in the legume or "bean" family (Fabaceae). It is an annual herbaceous legume and a warm-season crop and need abundant sunshine and a warm climate for its normal growth. The most suitable soils are well-drained loose, friable, sandy loam, well supplied with lime and with moderate (but not high) amount of organic matter. Groundnut requires five months of warm weather. The pod ripen 120 to 150 days after the seeds are planted. If the crop is harvested too early, the pods will be unripe. If they are harvested late, the pods will snap off at the stalk, and will remain in the soil. Groundnut is particularly susceptible to contamination during growth and storage. Poor storage can lead to an infection by the mold fungus Aspergillus flavus, releasing the toxic and highly carcinogenic substance aflatoxin. The aflatoxin producing molds exist throughout the peanut growing areas and may produce aflatoxin in peanuts when conditions are favorable to fungal growth.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (35, 'Sunflower', 'Helianthus annuus', 3, 'Sunflower oil, extracted from the seeds, is used for cooking, as carrier  oil and to produce margarine and bio-diesel, as it is cheaper than olive  oil.', 2, 0, NULL, 'Helianthus annuus', 'HARC', 9, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Sunflower.jpg', 'ሱፍ', 'sunflower', 'croptype-671707385473', 'oil-seeds', 'Sunflower is native to the Central America. Sunflower oil is used for cooking, as carrier oil and to produce margarine and bio-deiseal. According to the Central Statistics The total area under production during 2020/21 was 4,150.55 hectares and the production was estimated to be over 42,878.01 quintals.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (36, 'Safflower', 'Carthamus tinctorius L.', 3, 'This herb is  highly branched with many long sharp spines on the leaves. Plants are  generally 30 to150 cm tall with globular flower heads (capitula) and  commonly, brilliant yellow, orange or red flowers. It is widely grown  for its red or orange flower heads and seeds that yield valuable oil.', 2, 50, NULL, 'Carthamus tinctorius L.', 'HARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Safflower.jpg', 'ሱፍ', 'safflower', 'croptype-784104217122', 'oil-seeds', 'Safflower is an annual composite plant from the asteraceae family. This herb is highly branched with many long sharp spines on the leaves. Plants are generally 30-50 cm tall with globular flower heads (capitula) and commonly, brilliant yellow, orange or red flowers. It is widely grown for its red or orange flower heads and seeds that yield valuable oil. Safflower seed oil is flavorless and colorless, and nutritionally similar to sunflower oil. It is used mainly in cosmetics and as cooking oil, in salad dressing, and for the production of margarine.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (37, 'Vernonia', 'Vernonia galamensis', 10, 'Vernonia galamensis is a new potential industrial crop with very high  content of vernolic acid in the seed oil. The products that can be made  from vernonia include epoxies for manufacturing adhesives, varnishes  and paints, and industrial coatings.', 0, 0, NULL, 'Vernonia galamensis', 'WGARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/vernonia.webp', NULL, 'vernonia', 'croptype-251112141583', 'industrial-crops', 'Vernonia galamensis is industrial crop with very high content of vernolic acid in the seed oil. The products that can be made from vernonia include epoxies for manufacturing adhesives, varnishes and paints, and industrial coatings. The low viscosity of Vernonial oil would allow it to be used as a non-volatile solvent in oil based-paints since it will become incorporated in the dry paint rather than evaporating in to the air, which reduces pollution.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (38, 'Castor', 'Ricinus communis L', 10, 'Castor seed is  the source of castor oil, which has a wide variety of uses. The seeds  contain between 40% and 60% oil that is rich in triglycerides, mainly  ricinolein. The seed contains ricin, a toxin, which is also present in  lower concentrations throughout the plant.', 0, 0, NULL, 'Ricinus communis L.', 'MARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Castor.jpg', 'ጉሎ', 'castor', 'croptype-078847480249', 'industrial-crops', 'Castor is a flowering plant in the spurge family, Euphorbiaceae. It is indigenous to the southeastern Mediterranean Basin, Eastern Africa, and India. Castor seed is the source of castor oil, which has a wide variety of uses. The seeds contain between 40 and 60% oil that is rich in triglycerides, mainly ricinolein. The seed contain ricin, a toxin, which is also present in lower concentrations through the plant.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (39, 'Camelina sativa', 'Camelina sativa', 10, 'The crop has multitude of uses  among which its edible oil being the major one. The seed oil of  Camelina contains an exceptional amount (up to 45 per cent) of omega3 fatty acids, as well as a unique antioxidant complex making the oil  very stable and resistant to heat and rancidity. Unlike any other omega3 oil, Camelina oil is perfectly suitable for use not only as a well  balanced omega-3 supplement, but also as a health promoting everyday  cooking oil.', 0, 0, NULL, 'Camelina sativa', 'HARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/camelina.jfif', NULL, 'camelina', 'croptype-169132888124', 'industrial-crops', 'Camelina (Camelina sativa) is an oleaginous plant from the Cruciferae family, which has been domesticated and extensively used in Europe and America for several thousand years. The crop has multitude of uses among which its edible oil being the major one. The seed oil of Camelina contains an exceptional amount (up to 45%) of omega-3 fatty acids, as well as a unique antioxidant complex making the oil very stable and resistant to heat and rancidity. Unlike any other omega-3 oil, camelina oil is perfectly suitable for use not only as a well balanced omega-3 supplement, but also as a health promoting everyday cooking oil.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'REVIEWED_TYPE_ALIAS', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (40, 'Irish potato', 'Solanum tuberosum', 5, 'It was  introduced to Ethiopia in 1858 and since then it has become an  important crop in many parts of the country. In volume of  production it ranks fourth in the world after maize, rice, and wheat.  Among root crops, potato ranks first in volume produced and  consumed, followed by cassava, sweet potato, and yam.', 0, 0, NULL, 'Solanum tubersum', 'HARC', 5, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/irishPotato.jpg', 'ድንች', 'potato', 'croptype-711524051980', 'roots-and-tubers', 'In volume of production potato ranks fourth in the world after maize, rice and wheat. Among root crops, potato ranks first in volume produced and consumed, followed by cassava, sweeet potato, and yam.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'REVIEWED_TYPE_ALIAS', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (41, 'Sweet potato', 'Ipomoea batatas', 5, 'Its large, starchy, sweet tasting tuberous roots are an  important root vegetable. The young leaves and shoots are sometimes  eaten as greens. It is one of the major root crops of Ethiopia, which is  cultivated around home for several years and is used for food and feed.', 0, 0, NULL, 'Ipomoea batatas', 'HawARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/sweet_potato.jpg', 'ስኳር ድንች', 'sweet-potato', 'croptype-310332039024', 'roots-and-tubers', 'Sweet potato is a dicotyledonous plant that belongs to the family Convolvulaceae. Its large, starchy, sweet tasting tuberous roots are an important root vegetable. The young leaves and shoots are sometimes eaten as greens. It is one of the major root crops of Ethiopia, which is cultivated around hoe for several years and is used for food and feed. Sweet potato is mostly cultivated in the south, southwest and east of the county.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (42, 'Taro', 'Colocasia esculenta', 5, 'It is a root crop of secondary importance grown in many parts of the  wet tropics, and does best on a moist or even slightly swampy soil. It is  known as taro in the Pacific Islands, eddo or dasheen in the West  Indies, as old cocoyam in West Africa and „Godere‟ in Ethiopia.', 0, 0, NULL, 'Colocasia esculenta', 'JARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/taro.jpg', NULL, 'taro', 'croptype-898168031958', 'roots-and-tubers', 'Taro is known as Godere in Ethiopia. The part eaten is the corm which is formed underwound by the thickening of the base of the stem. The crop is propagated by cutting from the top part of the corm or by planting cormels.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (43, 'Cassava', 'Manihot esculenta', 5, 'The  carbohydrate rich but low in protein storage roots represent an  important energy source and are a staple food stuff for more than 500  million people throughout tropical Africa, Latin America and parts of  Asia. Cassava can grow under poor soil conditions and can withstand  drought. It is therefore usually considered as an important famine  reserve crop in countries with unreliable rainfall.', 0, 0, NULL, 'Manihot esculenta', 'HawARC', 2, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/casava.jpg', NULL, 'cassava', 'croptype-210865675426', 'roots-and-tubers', 'Cassava is widely cultivated in many parts of the world. It is a perennial shrub, with latex in all its parts, which produces enlarged tuberous root. Cassava root is eaten as a vegetable, and as it toxic raw it is eaten after cooking.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (44, 'Enset', 'Ensete ventricosum (Welw.) Cheesman', 5, 'It is Ethiopia''s most important root  crop, a traditional staple crop in the densely populated south and  southwestern parts of Ethiopia. Enset provides more amount of food  stuff per unit area than most cereals.', 0, 0, NULL, 'Ensete ventricosum (Welw.) Cheesman', 'AreARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/enset.jpg', 'እንሰት', 'enset', 'croptype-332505833002', 'roots-and-tubers', 'Enset is commonly known as "false banana" for its close resemblances to the domesticated banana plant.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (45, 'Yam', 'Dioscorea spp', 5, 'This  thick, tropical-vine tuber is popular in Africa, the West Indies, and  parts of Asia, South and Central America. By virtue of its excellent  palatability, it is a high value crop. Yams are cultivated throughout the  tropics, and in parts of the sub-tropics and temperate zones. In West  Africa and New Guinea, the yam is a primary agricultural commodity.', 0, 0, NULL, 'Dioscorea spp', 'HawARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/yam.jpg', NULL, 'yam', 'croptype-914145610558', 'roots-and-tubers', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (46, 'Tomato', 'Lycopersicum esculentum.Mill', 5, 'It is an important cash-generating crop to small scale farmers and provides employment in the production and  processing industries. It is also important source of vitamin A and C as  well as minerals', 2, 0, NULL, 'Lycopersicum esculentum. Mill', 'MARC', 6, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/tomato.jpg', 'ቲማቲም', 'tomato', 'croptype-322963603333', 'fruit-and-vegetables', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (47, 'Garlic', 'Allium Sativum.', 5, 'Garlic is used as a seasoning in many foods worldwide, without garlic  many of our popular dishes would lack the flavor and character that  make them favorites. Garlic''s volatile oil has many sulfur containing  compounds that are responsible for the strong odor, its distinctive  flavor and pungency as well as for its healthful benefits.  Medicinal activity seems to be highest in fresh garlic or garlic oil with  high allicin content.', 0, 0, NULL, 'Allium sativum', 'DZARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/garlic.jpg', 'ነጭ ሽንኩርት', 'garlic', 'croptype-142136063871', 'fruit-and-vegetables', 'Garlic (Allium sativum L, 2n=16) belongs to the family Alliaceae and is the second most widely used Allium next to onion. In Ethiopia, small growers in the highlands grow garlic traditionally but due to faulty cultural practices, yields are generally low. The yield in large-scale production with irrigation is expected to be about 10tons per hectre. Garlic is adapted to cool climates and should not generally be planted at an altitude below 2000 masl. The amount of rainfall during the growing period (4.5 to 6 months) should be 600 mm to 700 mm. The optimum temperature for growing garlic lies between 12 and 24oC.
During 2020/21 Meher cropping season, the total area under production reaches 15,979.54 ha and the production is estimated to be 1,149,446.97 quintals', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (48, 'Onion', 'Allium cepa L.', 5, 'It is considerably important in the  daily Ethiopian diet. All the plant parts are edible, but the bulbs and the  lower stems sections are the most popular as seasonings or as  vegetables in stews.', 0, 0, NULL, 'Allium cepa L.', 'MARC', 3, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/onion.jpg', 'ሽንኩርት', 'onion', 'croptype-957663023880', 'fruit-and-vegetables', 'Onion is one of the bulb crops belonging to the family Alliaceae. It is an important bulb crop in Ethiopia. It is considerably important in the daily Ethiopian diet. All plant parts are edible, but the bulbs and the lower stem sections are the most popular as seasonings or as vegetables in stews.

Onion contributes substantially to the national economy, adapt from overcoming local demands. Products like bulbs and cut flowers are exported to different countries of the world. With the growing irrigated agriculture in the country, there is great potential for extensive onion seed and dry bulb production in the different production belts of the country. Onion prefers well-drained sandy loam with a high content of organic matter. The optimum altitude range for Onion production is between 700 and 2200 masl. and the optimum growing temperature lies between 15oC and 23oC.
During 2020/21 Meher cropping season, the total area under production reaches over 38,952.58 hectares and the production is estimated to be over 3,460,480.88 quintals.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (49, 'Shallot', 'Allium cepa var. asculonicum Barker; syn.   A. ascalonicum auct. non L.', 5, 'widely cultivated as a source of income by  peasant farmers in many parts of the Ethiopia. They have a wide range  of climatic and soil adaptation and are cultivated both under rain-fed  and irrigated conditions. They are grown primarily for the bulb,  although the green tops may also be consumed.', 0, 0, NULL, 'Allium cepa var. asculonicum Barker', 'DZARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/shallot.jpg', 'ሽንኩርት', 'shallot', 'croptype-278506332520', 'fruit-and-vegetables', 'Shallot (Allium cepa var. asculonicum Barker, syn. A. ascalonicum auct.non L.) is believed to have come from Western Asia. It is perennial and seldom produces seeds, but the bulb when planted divides into a number of cloves, which remain attached at the bottom.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (50, 'Sweet/Hot Pepper', 'Capsicum annum) and Chili  (Capsicum frutenscens', 5, 'It is one of the most important  vegetable crops for fresh consumption (as chilies), for processing and  as a spice (for making stew). It is also a very important crop for spice  extraction since it has a lot of Oleoresin for dying of food items', 0, 0, NULL, 'Capsicum frutescence', 'MARC', 5, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Chili-Pepper-800x416.jpg', 'ቃሪያ', 'pepper', 'croptype-254997560878', 'fruit-and-vegetables', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'REVIEWED_TYPE_ALIAS', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (51, 'Cabbage', 'Brassica oleracea', 5, 'Cabbage is alkaline in reaction, high in cellulose or roughage, and has  very low calorie content and is very effective in helping overcome  constipation, and sauerkraut, or sauerkraut juice, is particularly good  for a sluggish intestinal tract, and for more serious cases of  constipation', 0, 0, NULL, 'Brassica oleracea', 'MARC', 3, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/cabbage.jpg', NULL, 'cabbage', 'croptype-776586950749', 'fruit-and-vegetables', 'Cabbage (Brassica oleracea, capitata group) has short stem and a globular head of tightly overlapping green to purplish leaves. In Ethiopia, the total area covered by head cabbage and Ethiopian cabbage in 2020/21 Meher cropping season was 51,114.46 ha and the total production during this season was about 4,891,287.23 quintals.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (52, 'Carrot', 'Daucus carota L.', 5, 'Carrot is particularly rich in carotene (pro-vitamin A). It is consumed  either fresh, as a salad crop, or cooked.', 0, 0, NULL, 'Daucus carota L.', 'Haramaya University', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/carrot.jpg', 'ካሮት', 'carrot', 'croptype-563334855049', 'fruit-and-vegetables', 'Carrot (Daucus corota L.) belongs to the family Apiaceae. It is rich in carotene (pro-vitamin A).

In Ethiopia, the area covered by carrot in 2020/21 Meher cropping season is about 3,717.22 ha and the total production is estimated to be 196,387.07 quintals.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (53, 'Okra', 'Abelmoschus esculentus L. Monech', 5, 'Okra is especially valued for its tender delicious fruits and is agood  source of iodine and calcium. Apart from its nutritive value, matured  fruits and stems containing crude fiber are used in paper industry. It can  be eaten grated raw or cooked. It possesses high nutritive value.', 0, 0, NULL, 'Abelmoschus esculentus L. Monech', NULL, 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/okra.jpg', NULL, 'okra', 'croptype-253966230443', 'fruit-and-vegetables', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (54, 'Anchote', 'Coccinia abyssinica', 5, 'It is a good source of vitamins, minerals protein and  calcium compared to other root crops. Therefore, it can be used as a  strategic crop to alleviate protein deficiency in areas of nutrition with  low protein source (Amsalu et al., 2008).The most widely used  vernacular name is Anchote, spelt ''Ancootee '' in Oromo. It is also  called: Ushushe (Wolaita), Shushe (Dawuro), and Ajjo (Kafigna)  (Amsalu et al., 2008).', 0, 0, NULL, 'Coccinia abyssinica', 'DZARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/anchoteq.jfif', 'አንጮቴ', 'anchote', 'croptype-140996057213', 'fruit-and-vegetables', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (55, 'Summer squash', 'Cucurbita pepo', 5, 'The entire  vegetable, including its flesh, seeds and skin, is edible. In addition,  some varieties of the squashes produce edible flowers. Unlike winter  squash, summers squash is more fragile and cannot be stored for long  period of time.', 0, 0, NULL, 'Cucurbita pepo', 'MARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/summer-squash.jpg', NULL, 'summer-squash', 'croptype-017503164196', 'fruit-and-vegetables', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (56, 'Summarsquash', 'Cucurbita pepo', NULL, 'Is a recent introduction and  cultivation to Ethiopia. Summer squash, members of the Cucurbitaceae  family and relatives of both the melon and the cucumber, come in  many different varieties. While each type varies in shape, color, size  and flavor, they all share some common characteristics. The entire  vegetable, including its flesh, seeds and skin, is edible.', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'UNRESOLVED', 'UNRESOLVED', 'UNRESOLVED'),
  (57, 'Coriander', 'Coriandrum sativum L.', 10, 'Spice', 0, 0, NULL, 'Coriandrum sativum L.', 'DZARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/coriander.jpg', 'ድምብላል', 'coriander', 'croptype-367727453468', 'spices-condiments-medicinal-aromatic', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
