  (101, 'Lupin', 'Lupinus spp.', NULL, 'It is  an ancient traditional multipurpose crop being cultivated particularly in  the North-western part of Ethiopia. In Ethiopia lupin is believed to  have originated and introduced into Ethiopia from Egypt. It is also  believed that the Amharic local name of lupin in Ethiopia, Gibto, has  been derived from the Amharic name of Egypt, Gibtsi.', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'UNRESOLVED', 'UNRESOLVED', 'UNRESOLVED'),
