  (108, 'Mulberry', 'Morus indica', NULL, 'Forage', 0, 0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'UNRESOLVED', 'UNRESOLVED', 'UNRESOLVED'),
  (109, 'Cotton', 'Gossypium hirsutum', 10, 'It is used to manufacture a wide variety of of hand woven  dresses and industrial processed textile fabrics, in addition to edible oil  and protein rich-seedcake production for human and animal  consumption respectively.', 0, 0, NULL, 'Gossypium hirsutum', 'WARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/cotton-field.webp', 'ጥጥ', 'cotton', 'croptype-306057170909', 'industrial-crops', 'Cotton is one of the major industrial and cash crops in Ethiopia, mainly supporting the textile and garment industry. The crop is predominantly grown in the country’s lowland irrigated and rain-fed areas with warm climates. The major cotton-growing areas include the Awash Valley (Afar and Oromia), Humera and Metema in Amhara, Gambella, Benishangul-Gumuz, and parts of South Ethiopia. The major potential production basins are Awash, Omo-Ghibe, Wabi-Shebelle, Baro-Akobo, Blue Nile, and Tekeze river basins. Recent studies indicate that Ethiopia cultivates only a small portion of its estimated cotton-suitable land despite having high potential. Cotton production in recent years has ranged roughly between 50,000–80,000 metric tons annually, with productivity commonly reported around 0.7–1.5 tons per hectare depending on irrigation, seed type, and management practices. Productivity in irrigated areas such as Afar and the Awash Basin is generally much higher than rain-fed systems. The government considers cotton a strategic crop because of its importance for the expanding textile and apparel sector, foreign exchange earnings, and employment generation. Recent efforts, including the introduction of improved and Bt cotton varieties, aim to improve productivity and quality.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (110, 'Kenaf', 'Hibiscus spp', 10, 'Kenaf  is being developed as a non wood fiber crop. The bark, which contains  long soft bast fibers, makes up 30 to 40% of the dry weight of the stem,  is an ideal blend of long short fibers', 0, 0, NULL, 'Hibiscus spp', 'WARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/kenaf.webp', NULL, 'kenaf', 'croptype-531239369740', 'industrial-crops', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (111, 'Sugarcane', 'Saccharum officinarum', 10, 'Sugarcane is the main sugar producing crop in Ethiopia and sugar  industry plays a significant role in the socio economy of the country.', 0, 0, NULL, 'Saccharum officinarum', 'Sugar Corporation', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/sugarcane.jpg', 'ሸንኮራ', 'sugarcane', 'croptype-926200460059', 'industrial-crops', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (112, 'Coffee', 'Coffea arabica L.', 10, 'Coffee is the most important agricultural commodity and beverage  enjoyed throughout the world. Coffee grows at various altitudes,  ranging from 550 to 2750 meters above sea level.', 0, 0, NULL, 'Coffea arabica L.', 'JARC', 0, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/coffee.webp', 'ቡና', 'coffee', 'croptype-871314011499', 'stimulant-crops', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (113, 'Tobaco', 'Nicotiana tabacum', 10, 'Tobacco is a stimulant and  the dried leaves of the tobacco plant can be cured and used to produces  tobacco cigarettes, cigars and snuff or for pesticide production.', 0, 0, NULL, 'Nicotiana tabacum', 'National Tobaco Enterprise', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/tobaco.jpg', 'ትምባሆ', 'tobaco', 'croptype-833789386136', 'industrial-crops', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (114, 'Adzuki bean', 'Adzuki bean (Vigna angularis)', 2, 'It is an annual bushy widely grown in  Japan and China for its seeds which are used as food and to produce a  flour', 2, 0, NULL, 'Vigna angularis', 'MARC', 2, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Adzuki bean.jpg', NULL, 'adzuki-bean', 'croptype-259092633826', 'food-legume', 'Adzuki bean (Phaseolus angularis) is an annual bushy widely grown in Japan and china for its seeds which are used as food and to produce a flour. The plant is erect, 0.3 to 0.6 meter high, although some gardeners have reported them to be indeterminate, growing and producing until frost.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'SQL_CROP_CATALOG'),
  (115, 'Lima bean', 'Lima bean /butter bean (Phaseolus lunatus)', 2, 'The crop has deep rooted, drought tolerant and  wide environmental adaptation character. It has numerous uses like  animal feed, soil improvement, human food (immature and dry seeds)  and medicine.', 2, 0, NULL, 'Phaseolus lunatus', 'Melkassa Agricultural Research Cent', 2, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/limabean.jpg', NULL, 'lima-bean-butter-bean', 'croptype-474245217289', 'food-legume', 'LIma bean (Phaseolus lunatus L.) is a species of beans which originated from the regions of Central America and Andes Mountains. The crop has distinctive features that include different types of pods, seed size, shape, thickness, color and growth forms. The crop is readily distinguished from other species in that it possesses fine ridges in the seed coat that radiate from the "eye". The pods are wide, flat, and slightly curved. The plant grows as a perennial in the tropics and is normally cultivated as an annual crop. It requires a longer season and warmer weather than most varieties of common bean (Phaseoulus vulgaris). It can grow within annual temperature 0f 16-27oC and annual ran fall 900-2000mm. The crop has deep rooted, drought tolerant and wide environmental adpatation character. It has numerous uses like animal feed, soil improvement, human food (immature and dry seeds) and medicine.', 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'REVIEWED_TYPE_ALIAS', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
  (116, 'Lettuce', 'Lactuca sativa', 5, 'Salad', 2, 0, NULL, 'Lactuca sativa', 'HARC', 1, 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/lettuce.jpg', NULL, 'lettuce', 'croptype-523478583483', 'fruit-and-vegetables', NULL, 'SQL_CROP_CATALOG', 'SQL_CROP_VARIETY', 'EXACT_NORMALIZED_NAME', 'MATCHED', 'WORKBOOK_TAXONOMY_MAPPING'),
